using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using HauntedFish.BossFight;
public static class BossCompositionIntegrationBatch{
 const string Armed="Haunted.BossComposition.Native.Armed";
