 static void State(PlayModeStateChange s){if(s!=PlayModeStateChange.EnteredPlayMode)return;SessionState.SetBool(Armed,false);EditorApplication.playModeStateChanged-=State;EditorApplication.delayCall+=()=>BossDefenseNativeRegression.RunInCurrentPlayScene();}
