 foreach(var cam in scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Camera>(true)))cam.rect=new Rect(0,0,1,1);
 foreach(var canvas in scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Canvas>(true)))canvas.enabled=false;
 var vs=new SerializedObject(view);vs.FindProperty("_FrameSize").vector3Value=new Vector3(7.3f,.7f,11.6f);vs.FindProperty("_AuthoredFrameMarkers").arraySize=0;vs.ApplyModifiedPropertiesWithoutUndo();
 var timber=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="Boss raised tray timber"};timber.color=new Color(.09f,.038f,.025f);if(AssetDatabase.LoadAssetAtPath<Material>("Assets/Resources/BossFight/SceneObjects/TrayTimber.mat"))UnityEngine.Object.DestroyImmediate(timber);timber=AssetDatabase.LoadAssetAtPath<Material>("Assets/Resources/BossFight/SceneObjects/TrayTimber.mat")??timber;if(!AssetDatabase.Contains(timber))AssetDatabase.CreateAsset(timber,"Assets/Resources/BossFight/SceneObjects/TrayTimber.mat");var trim=new Material(timber){name="Boss aged tray trim"};trim.color=new Color(.24f,.16f,.07f);if(AssetDatabase.LoadAssetAtPath<Material>("Assets/Resources/BossFight/SceneObjects/TrayTrim.mat"))UnityEngine.Object.DestroyImmediate(trim);trim=AssetDatabase.LoadAssetAtPath<Material>("Assets/Resources/BossFight/SceneObjects/TrayTrim.mat")??trim;if(!AssetDatabase.Contains(trim))AssetDatabase.CreateAsset(trim,"Assets/Resources/BossFight/SceneObjects/TrayTrim.mat");BossTrayArtworkAuthoring.Tray(board.transform,false,timber,trim);BossTrayArtworkAuthoring.Tray(board.transform,true,timber,trim);
 for(int slot=0;slot<6;slot++){var piece=board.Piece(slot);piece.transform.position=new Vector3(1000+(slot<3?-4.15f:4.15f),1.62f,(slot<3?-2:2)+(slot%3-1));if(slot%3!=2)continue;var ps=new SerializedObject(piece);foreach(string field in new[]{"_Healthy","_Broken","_ValidPreview","_InvalidPreview"}){var old=(GameObject)ps.FindProperty(field).objectReferenceValue;var replacement=BossTrayArtworkAuthoring.Building(piece.transform,field=="_Broken");replacement.SetActive(field=="_Healthy");if(field.Contains("Preview")){var color=AssetDatabase.LoadAssetAtPath<Material>("Assets/Resources/BossFight/Defenses/"+(field=="_ValidPreview"?"Valid":"Invalid")+".mat");foreach(var r in replacement.GetComponentsInChildren<Renderer>())r.sharedMaterials=Enumerable.Repeat(color,r.sharedMaterials.Length).ToArray();}ps.FindProperty(field).objectReferenceValue=replacement;UnityEngine.Object.DestroyImmediate(old);}ps.ApplyModifiedPropertiesWithoutUndo();}
 if(!board.ValidateAuthoredBindings(out var error))throw new Exception(error);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllText("Tools/BossFightTests/Evidence/composition/visual-results.txt","Native modular composition and six building/bottle/tuna slots authored; raised trays; full camera viewport; footer disabled. Render acceptance pending.");SessionState.SetBool(Armed,true);EditorApplication.playModeStateChanged-=State;EditorApplication.playModeStateChanged+=State;EditorApplication.EnterPlaymode();}
